"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["94490"],{5935(e){e.exports=JSON.parse('{"id":"FIN-1050","slug":"restricted-stock-unit","term":"Restricted Stock Unit","also_known_as":[],"difficulty":"Advanced","definition":"A restricted stock unit (RSU) is a promise by an employer to give an employee shares in the company, or their cash value, once certain conditions are met, usually continuing to work for the company for a set period.","explanation":["RSUs are a common form of equity pay, especially at listed technology companies. Unlike stock options, RSUs do not require the employee to pay anything to receive the shares, so they have value as long as the share price is above zero.","RSUs are granted with a vesting schedule. For example, an employee might receive 1,000 RSUs vesting in equal parts over four years. When each portion vests, the employee receives the shares. If the share price is 50 at vesting, 250 shares are worth 12,500.","In many countries, the value of RSUs is taxed as employment income when they vest, even if the shares are not sold. Companies often withhold some shares to cover the tax.","For the company, RSUs are a form of share-based compensation, expensed over the vesting period based on the share price at grant. Some RSUs, called performance stock units, vest only if targets such as profit or share price goals are met."],"note":"","total":1725,"prev":{"slug":"restricted-stock","term":"Restricted Stock"},"next":{"slug":"restructuring","term":"Restructuring"}}')}}]);